BEGIN TRANSACTION;
CREATE TABLE bot_groups (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    cash REAL NOT NULL,  -- money not handed to any of its bots
    money_in REAL NOT NULL,  -- all the money put in: its starting amount plus any added since
    created_at INTEGER NOT NULL
, closed_at INTEGER);
CREATE TABLE bots (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    product TEXT NOT NULL,
    timeframe TEXT NOT NULL,
    strategy TEXT NOT NULL,
    starting_cash REAL NOT NULL,
    cash REAL NOT NULL,
    position REAL NOT NULL DEFAULT 0,
    entry_price REAL,
    start_price REAL NOT NULL,
    created_at INTEGER NOT NULL,
    last_candle_ts INTEGER
, fee_rate REAL, slippage REAL, stop_atr REAL, stop_distance REAL, peak_price REAL, stopped_out INTEGER NOT NULL DEFAULT 0, name TEXT, settings TEXT, stop_floor REAL, take_profit_price REAL, entry_candle_ts INTEGER, bot_type TEXT, state TEXT, maker_fee REAL, paused INTEGER NOT NULL DEFAULT 0, error_count INTEGER NOT NULL DEFAULT 0, last_error TEXT, limit_orders INTEGER, pending_order TEXT, group_id INTEGER, finished_at INTEGER, final_equity REAL);
CREATE TABLE candles (
    product TEXT NOT NULL,
    timeframe TEXT NOT NULL,
    ts INTEGER NOT NULL,
    open REAL NOT NULL,
    high REAL NOT NULL,
    low REAL NOT NULL,
    close REAL NOT NULL,
    volume REAL NOT NULL, fetched_at INTEGER,
    PRIMARY KEY (product, timeframe, ts)
);
CREATE TABLE changes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    bot_id INTEGER NOT NULL REFERENCES bots(id) ON DELETE CASCADE,
    ts INTEGER NOT NULL,
    before TEXT NOT NULL,  -- JSON settings
    after TEXT NOT NULL,
    note TEXT  -- what changed, in words
);
CREATE TABLE equity (
    bot_id INTEGER NOT NULL REFERENCES bots(id) ON DELETE CASCADE,
    ts INTEGER NOT NULL,
    equity REAL NOT NULL,
    price REAL NOT NULL, kind TEXT,
    PRIMARY KEY (bot_id, ts)
);
CREATE TABLE group_equity (
    group_id INTEGER NOT NULL REFERENCES bot_groups(id) ON DELETE CASCADE,
    ts INTEGER NOT NULL,
    equity REAL NOT NULL,  -- its cash plus its bots
    hodl REAL NOT NULL,  -- the same with each bot holding its coin from its start
    money_in REAL NOT NULL,
    PRIMARY KEY (group_id, ts)
);
CREATE TABLE predictions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    product TEXT NOT NULL,
    timeframe TEXT NOT NULL,
    strategy TEXT NOT NULL,
    candle_ts INTEGER NOT NULL,
    created_at INTEGER NOT NULL,
    price REAL NOT NULL,
    action TEXT NOT NULL,
    score REAL NOT NULL,
    horizon INTEGER NOT NULL,
    target_ts INTEGER NOT NULL,
    features TEXT NOT NULL,
    components TEXT NOT NULL,
    outcome_price REAL,
    outcome_return REAL,
    correct INTEGER,
    evaluated_at INTEGER,
    UNIQUE (product, timeframe, strategy, candle_ts)
);
CREATE TABLE reviews (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    bot_id INTEGER NOT NULL REFERENCES bots(id) ON DELETE CASCADE,
    ts INTEGER NOT NULL,
    note TEXT  -- what it found, in a few words
);
CREATE TABLE state (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
);
CREATE TABLE trades (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    bot_id INTEGER NOT NULL REFERENCES bots(id) ON DELETE CASCADE,
    ts INTEGER NOT NULL,
    signal_candle_ts INTEGER NOT NULL,
    side TEXT NOT NULL,
    price REAL NOT NULL,
    size REAL NOT NULL,
    fee REAL NOT NULL,
    cash_after REAL NOT NULL,
    position_after REAL NOT NULL,
    pnl REAL,
    score REAL NOT NULL,
    reason TEXT NOT NULL
, kind TEXT);
CREATE INDEX predictions_pending ON predictions (product, timeframe, evaluated_at);
DELETE FROM "sqlite_sequence";
COMMIT;
